WITH flattened_attrs AS (SELECT id, created_at, items, ship_to, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS basket_amount, FORALL(items, li -> li.qty <= 5) AS all_small_qty FROM carts) SELECT id, basket_amount, ROW_NUMBER() OVER w_part AS seq_no, RANK() OVER (ORDER BY basket_amount DESC) AS basket_amount_rank FROM flattened_attrs WHERE basket_amount BETWEEN 500 AND 800 WINDOW w_part AS (ORDER BY basket_amount DESC, id);
